'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var sincosdf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( sincosdf instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof sincosdf, 'function', 'main export is a function' );
	t.end();
} );

tape( 'computes sine and cosine using native addon', opts, function test( t ) {
	var v;

	try {
		v = sincosdf( 0.0 );
		t.equal( v[ 0 ], 0.0, 'sine(0) is 0' );
		t.equal( v[ 1 ], 1.0, 'cosine(0) is 1' );
	} catch ( err ) {
		t.ok( false, err.message );
	}
	t.end();
} );
